/**
 * seed.mjs — read a generation seed file that is NOT part of this repo.
 *
 * This repository holds the engine and the world-building tools only: no
 * world data, no seed data. Seeds live in S3 (see DATA.md) and are fetched
 * into scripts/**\/data/ before use; some can also be regenerated by the
 * fetch scripts (scripts/sol-real/fetch-*.mjs) or read back from the world
 * database (<db-host>/<db-name> — worlds, bodies, atoms, stars).
 */
import { readFileSync } from 'node:fs'

/** Read a seed file, with a clear message when it has not been fetched yet. */
export function readSeed(path, hint) {
  try {
    return readFileSync(path, 'utf8')
  } catch {
    console.error(`\nSeed file not found: ${path}`)
    console.error('Seed data is not part of this repo — see DATA.md.')
    if (hint) console.error(`For this seed: ${hint}`)
    process.exit(1)
  }
}
